import React from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';

const MapComponent = ({ vehicles, stations, onMapClick }) => {
  useMapEvents({
    click: (e) => {
      onMapClick([e.latlng.lat, e.latlng.lng]);
    },
  });

  return (
    <>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      {vehicles.map((vehicle, index) => (
        <Marker key={index} position={vehicle.location} icon={VehicleIcon}>
          <Popup>{vehicle.name}</Popup>
          <Popup>{vehicle.battery}</Popup>
          <Popup>{vehicle.steps}</Popup>
        </Marker>
      ))}
      {stations.map((station, index) => (
        <Marker key={index} position={station.location} icon={StationIcon}>
          <Popup>{station.name}</Popup>
        </Marker>
      ))}
    </>
  );
};

const MapWrapper = (props) => (
  <MapContainer center={[51.505, -0.09]} zoom={13} style={{ height: '100%', width: '100%' }}>
    <MapComponent {...props} />
  </MapContainer>
);

export default MapWrapper;
